import sys

def power(base, exp):
    """Return base raised to the integer exponent exp without using ** or pow()."""
    if exp == 0:
        return 1
    invert = False
    if exp < 0:
        invert = True
        exp = -exp
    result = 1
    while exp:
        if exp & 1:
            result *= base
        base *= base
        exp >>= 1
    return 1 / result if invert else result

