import math

def nth_prime(n):
    if n == 1:
        return 2

    if n < 6:
        limit = 13
    else:
        log_n = math.log(n)
        limit = int(n * (log_n + math.log(log_n))) + 3

    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'

    for p in range(2, int(limit ** 0.5) + 1):
        if sieve[p]:
            sieve[p*p:limit+1:p] = b'\x00' * (((limit - p*p) // p) + 1)

    count = 0
    for i in range(limit + 1):
        if sieve[i]:
            count += 1
            if count == n:
                return i

    candidate = limit + 1
    while True:
        is_prime = True
        if candidate > 1:
            for d in range(2, int(candidate ** 0.5) + 1):
                if candidate % d == 0:
                    is_prime = False
                    break
            if is_prime:
                count += 1
                if count == n:
                    return candidate
        candidate += 1
